'use client';
import {useCallback,useEffect,useRef,useState} from 'react';
import {formText,hotelRpc} from '@/lib/pilot';
import {downloadReport,reportUsd} from '@/lib/report-export';
import {useClientReady} from '@/lib/client-ready';
import {depositAmount,depositDetailCsv,depositKey,depositKinds,depositMethods,depositPostArgs,depositRetireArgs,depositStatusLabel,depositText,validateDepositDetail,validateDepositOutcome,validateDepositPending,validateDepositStatus,type DepositBook,type DepositCommand,type DepositDetail,type DepositEvent,type DepositKind,type DepositMethod,type DepositOutcome,type DepositPending,type DepositReservation,type DepositScope,type DepositTotals} from '@/lib/deposits';

type Props=DepositScope&{propertyName:string;disabled?:boolean;onBusyChange:(busy:boolean)=>void;onSaved:()=>void|Promise<void>};
type Proposal={command:DepositCommand;review:{book:DepositBook|null;target_remaining_minor:number|null}};
export function DepositTotalsView({totals}:{totals:DepositTotals}){return <div className="detail-grid"><div>Recorded received<b>{reportUsd(totals.received_minor)}</b></div><div>Recorded returned<b>{reportUsd(totals.refunded_minor)}</b></div><div>Receipt reductions<b>{reportUsd(totals.reduced_minor)}</b></div><div>Recorded security funds remaining<b>{reportUsd(totals.held_minor)}</b></div></div>}
export function DepositHistory({events,reservations,onOpen}:{events:DepositEvent[];reservations?:Record<string,DepositReservation>;onOpen?:(reservation:string)=>void}){return <div className="pilot-table-wrap"><table className="pilot-table"><caption>Immutable security-deposit entries</caption><thead><tr>{reservations&&<th scope="col">Current stay</th>}<th scope="col">Recorded date / entry</th><th scope="col">Amount</th><th scope="col">Evidence</th><th scope="col">Details</th></tr></thead><tbody>{events.map(e=>{const stay=reservations?.[e.reservation_id];return <tr key={e.id}>{reservations&&<td>{stay?.guest_name??'Guest name unavailable'}<small>{stay?.source_booking_id??'Reference unavailable'} · {stay?depositStatusLabel(stay):'Status unavailable'}</small>{onOpen&&<button className="text-button" onClick={()=>onOpen(e.reservation_id)}>Open deposit record</button>}</td>}<td>{e.recording_date}<small>{depositKinds[e.kind]}</small></td><td>{reportUsd(e.amount_minor)}<small>{e.recorded_method?depositMethods[e.recorded_method]:'No money movement'}</small></td><td>{e.reference}<small>{e.reason}</small></td><td><details><summary>Audit details</summary><p>Recorded {e.recorded_at} · {e.recording_time_zone}</p><p>Entry {e.id}<br/>Request {e.request_id}<br/>Actor {e.actor_id}<br/>Book version {e.from_version} → {e.to_version}</p>{e.target_event_id&&<p>Original receipt {e.target_event_id}</p>}</details></td></tr>})}</tbody></table>{!events.length&&<p>No security-deposit entries recorded.</p>}</div>}
export function DepositPanel(props:Props){return useClientReady()?<DepositForm key={depositKey(props)} {...props}/>:<p>Loading security-deposit recovery…</p>}

function DepositForm(props:Props){
 const {actor,tenant,property,reservation,propertyName,disabled=false,onBusyChange,onSaved}=props,storageKey=depositKey(props);
 const [initial]=useState(()=>{try{const raw=sessionStorage.getItem(storageKey);if(!raw)return {pending:null,error:''};const value:unknown=JSON.parse(raw);validateDepositPending(value,{actor,tenant,property,reservation});return {pending:value,error:''}}catch{return {pending:null,error:'The saved security-deposit request cannot be read. Keep this browser record for reconciliation before entering another request.'}}});
 const [pending,setPending]=useState<DepositPending|null>(initial.pending),[data,setData]=useState<DepositDetail|null>(null),[fresh,setFresh]=useState(false),[loading,setLoading]=useState(true),[busy,setBusy]=useState(false),[error,setError]=useState(initial.error),[notice,setNotice]=useState(''),[kind,setKind]=useState<DepositKind>('external_receipt'),[proposal,setProposal]=useState<Proposal|null>(null),[retirementReason,setRetirementReason]=useState(initial.pending?.retirement_reason??''),[revision,setRevision]=useState(0);
 const alive=useRef(true),sequence=useRef(0),lock=useRef(false),busyCallback=useRef(onBusyChange);
 useEffect(()=>{busyCallback.current=onBusyChange},[onBusyChange]);
 const releaseBusy=useCallback(()=>{if(lock.current){lock.current=false;busyCallback.current(false)}},[]);
 const invalidate=useCallback(()=>{alive.current=false;sequence.current++;releaseBusy()},[releaseBusy]);
 const read=useCallback(async()=>{const value=await hotelRpc<unknown>('security_deposit',{p_tenant:tenant,p_property:property,p_reservation:reservation});validateDepositDetail(value,tenant,property,reservation);return value},[tenant,property,reservation]);
 useEffect(()=>{alive.current=true;const version=++sequence.current;void read().then(value=>{if(alive.current&&version===sequence.current){setData(value);setFresh(true);setLoading(false)}}).catch(e=>{if(alive.current&&version===sequence.current){setError(e instanceof Error?e.message:'Unable to load security deposits.');setLoading(false);setFresh(false)}});return invalidate},[read,invalidate]);
 const blocked=disabled||busy;
 async function task(fn:()=>Promise<unknown>){if(disabled||lock.current||initial.error)return;lock.current=true;setBusy(true);busyCallback.current(true);setError('');try{await fn()}catch(e){if(alive.current){setError(e instanceof Error?e.message:'Unable to complete the security-deposit request.');setFresh(false)}}finally{lock.current=false;if(alive.current){setBusy(false);busyCallback.current(false)}}}
 async function refreshData(){const version=++sequence.current;setFresh(false);const value=await read();if(alive.current&&version===sequence.current){setData(value);setFresh(true);setLoading(false);setProposal(null);setRevision(v=>v+1)}return value}
 function preserve(value:DepositPending){validateDepositPending(value,{actor,tenant,property,reservation});sessionStorage.setItem(storageKey,JSON.stringify(value));setPending(value)}
 function clear(){sessionStorage.removeItem(storageKey);setPending(null);setRetirementReason('');setProposal(null)}
 async function confirmed(value:unknown,p:DepositPending){validateDepositOutcome(value,p);if(!alive.current)return;const outcome=value as DepositOutcome;setNotice(outcome.outcome==='retired'?'This request is stopped. It cannot add a deposit entry. No recorded funds were changed.':'Security-deposit entry confirmed. This receipt describes the original accepted record.');try{clear()}catch{setError('The browser could not remove this saved request. Keep it and use Check saved deposit request before another entry.')}try{await refreshData()}catch(e){if(alive.current){setFresh(false);setError('The outcome is confirmed, but current records could not refresh. Refresh before another entry. '+(e instanceof Error?e.message:''))}}if(alive.current)try{await onSaved()}catch{if(alive.current){setFresh(false);setError("The deposit outcome is confirmed, but the workspace could not refresh. Refresh before another entry.")}}}
 async function status(p:DepositPending){const result=await hotelRpc<unknown>('security_deposit_request_status',{p_tenant:tenant,p_property:property,p_request:p.request});validateDepositStatus(result,p);return result}
 async function check(){if(!pending)return;const p=pending;await task(async()=>{let current:DepositDetail|null=null;try{current=await refreshData()}catch{if(alive.current)setFresh(false)}if(!alive.current)return;const result=await status(p);if(!alive.current)return;if(result.found){await confirmed(result.result,p);return}if(p.retirement_reason===null&&current&&current.version>p.command.expected_version){clear();setNotice('No entry was recorded for this request, and a newer book version prevents it from being accepted. Review a new entry before sending.');return}setNotice(p.retirement_reason?'Stopping this request is still unconfirmed. Check again or retry stopping it with the saved reason.':'No saved outcome was found. Keep this exact request, retry it when appropriate, or review stopping its future retries. A missing result alone does not prove an earlier send failed.')})}
 async function send(p:DepositPending){await task(async()=>{preserve(p);setFresh(false);setProposal(null);try{const result=await hotelRpc<unknown>('record_security_deposit',depositPostArgs(p));await confirmed(result,p)}catch(e){if(alive.current)setError('The deposit result is unconfirmed. Check the saved request before any new entry. '+(e instanceof Error?e.message:''))}})}
 async function retire(){if(!pending)return;const original=pending;await task(async()=>{const p={...original,retirement_reason:original.retirement_reason??depositText(retirementReason,4,500)};preserve(p);setFresh(false);try{const result=await hotelRpc<unknown>('retire_security_deposit_request',depositRetireArgs(p));await confirmed(result,p)}catch(e){if(alive.current)setError('Stopping this request is unconfirmed. Its original command and retirement reason remain saved. Check the outcome or retry stopping it. '+(e instanceof Error?e.message:''))}})}
 async function review(form:HTMLFormElement){if(pending||!fresh||!data?.can_manage)return;const fields=new FormData(form);await task(async()=>{const amount=depositAmount(formText(fields,'amount')),reference=depositText(formText(fields,'reference'),4,200),reason=depositText(formText(fields,'reason'),4,500),target=kind==='external_receipt'?null:formText(fields,'target'),method=kind==='receipt_reduction'?null:formText(fields,'method') as DepositMethod;const current=await refreshData();if(!alive.current)return;if(!current.can_manage)throw Error('Your current role can read deposits but cannot add financial entries.');if(current.version>=1000)throw Error('This book has reached its 1,000-entry limit. Keep its history for reconciliation.');const remaining=target?current.refundable_receipts.find(row=>row.event_id===target)?.remaining_minor??null:null;if(target&&(!remaining||remaining<amount))throw Error('The selected receipt no longer has enough remaining recorded funds. Review the current record.');const next:Proposal={command:{reservation_id:reservation,expected_version:current.version,expected_recording_time_zone:current.recording_time_zone,expected_recording_date:current.recording_date,kind,amount_minor:amount,method,reference,reason,target_event_id:target,confirmed:true},review:{book:current.book,target_remaining_minor:remaining}};validateDepositPending({schema_version:1,actor,tenant,property,reservation,request:crypto.randomUUID(),...next,retirement_reason:null},{actor,tenant,property,reservation});setProposal(next)})}
 function confirm(){if(!proposal||pending||!fresh||!data?.can_manage||blocked)return;void send({schema_version:1,actor,tenant,property,reservation,request:crypto.randomUUID(),...proposal,retirement_reason:null})}
 const canWrite=fresh&&!!data?.can_manage&&!pending&&!initial.error;
 return <section className="pilot-folio"><p>Record refundable security funds received or returned outside iRatePilot. These entries do not collect money, change the guest folio, or change revenue.</p>{error&&<div className="pilot-error" role="alert">{error}</div>}{notice&&<output className="pilot-notice">{notice}</output>}<div className="pilot-actions"><button className="secondary" disabled={blocked||!!initial.error} onClick={()=>void task(refreshData)}>Refresh deposit record</button><button className="secondary" disabled={blocked||!fresh||!data||!!pending} onClick={()=>{if(data&&fresh)downloadReport(propertyName+'-security-deposit-'+reservation,depositDetailCsv(data,propertyName))}}>Export deposit history CSV</button></div>
  {pending&&<section className="pilot-settings"><h3>Resolve the saved deposit request</h3><p>{depositKinds[pending.command.kind]} · {reportUsd(pending.command.amount_minor)} · {pending.command.reference}</p><p>{pending.command.reason}</p><p>Reviewed recording date {pending.command.expected_recording_date} · {pending.command.expected_recording_time_zone}. Check the original outcome before another entry.</p><button className="primary" disabled={blocked} onClick={()=>void check()}>Check saved deposit request</button>{pending.retirement_reason===null&&fresh&&data?.can_manage&&<button className="secondary" disabled={blocked} onClick={()=>void send(pending)}>Retry exact deposit request</button>}<details><summary>Stop future retries</summary><p>This does not reverse a transaction. If the entry already recorded, its original receipt will be recovered. Otherwise this request will be permanently prevented from recording.</p>{pending.retirement_reason===null?<form onSubmit={e=>{e.preventDefault();void retire()}}><label className="field">Reason to stop this request<input value={retirementReason} onChange={e=>setRetirementReason(e.target.value)} minLength={4} maxLength={500} required disabled={blocked}/></label><label className="pilot-check"><input type="checkbox" required disabled={blocked}/>I reviewed this request and want to stop future retries if it has not recorded.</label><button className="secondary" disabled={blocked}>Stop retrying this request</button></form>:<><p>Saved stop reason: {pending.retirement_reason}</p><button className="secondary" disabled={blocked} onClick={()=>void retire()}>Retry stopping this request</button></>}</details><details><summary>Saved request identity</summary><p>Request {pending.request}<br/>Reservation {pending.reservation}<br/>Reviewed version {pending.command.expected_version}</p></details></section>}
  {loading&&!data?<p>Loading security-deposit records…</p>:data&&<><div className="section-top"><div><h3>{data.reservation.guest_name??'Reservation security deposit'}</h3><p>{data.reservation.source_booking_id} · {depositStatusLabel(data.reservation)} · {data.reservation.arrival??'Unknown arrival'} to {data.reservation.departure??'Unknown departure'}</p></div></div>{!fresh&&<p className="pilot-notice">This is a prior loaded snapshot. Refresh before a new entry or export.</p>}{data.totals?<DepositTotalsView totals={data.totals}/>:<p>No security-deposit book has been recorded for this reservation. This does not establish a zero deposit balance or reclassify earlier folio payments.</p>}<p>Recording date {data.recording_date} · {data.recording_time_zone}. The book keeps this recording zone if the property zone later changes.</p>{data.totals&&data.totals.held_minor>0&&['Checked out','Cancelled'].includes(data.reservation.status)&&<p className="pilot-notice">This ended stay still has recorded security funds remaining. Review the external records; this is not approval to refund.</p>}<DepositHistory events={data.events}/>{data.refundable_receipts.length>0&&<details><summary>Original receipt balances</summary>{data.refundable_receipts.map(row=><p key={row.event_id}>{data.events.find(e=>e.id===row.event_id)?.reference??row.event_id} · {reportUsd(row.remaining_minor)} remaining recorded funds</p>)}</details>}<p className="muted">Snapshot {data.generated_at}. Received − returned − record reductions = recorded security funds remaining.</p>{!data.can_manage&&<p>Your current role can read these records and recover your own saved outcomes. Owners and managers record new financial entries.</p>}</>}
  {canWrite&&!proposal&&data&&<form key={kind+'/'+revision} onSubmit={e=>{e.preventDefault();void review(e.currentTarget)}}><h3>Record external security funds</h3><p>Review existing entries for duplicates. A document or batch reference may be used more than once; a new request is not automatically a different real transaction.</p><label className="field">Security-deposit entry type<select value={kind} disabled={blocked} onChange={e=>setKind(e.target.value as DepositKind)}>{Object.entries(depositKinds).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label>{kind!=='external_receipt'&&<label className="field">Original received deposit<select name="target" required disabled={blocked}><option value="">Choose original receipt</option>{data.refundable_receipts.filter(row=>row.remaining_minor>0).map(row=><option key={row.event_id} value={row.event_id}>{data.events.find(e=>e.id===row.event_id)?.reference??row.event_id} · {reportUsd(row.remaining_minor)} remaining</option>)}</select></label>}<div className="form-grid"><label className="field">Security amount (USD)<input name="amount" inputMode="decimal" required disabled={blocked}/></label>{kind!=='receipt_reduction'&&<label className="field">Recorded external method<select name="method" required disabled={blocked}><option value="">Select method</option>{Object.entries(depositMethods).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label>}</div><label className="field">Deposit document reference<input name="reference" minLength={4} maxLength={200} required disabled={blocked}/></label><label className="field">Deposit record reason<input name="reason" minLength={4} maxLength={500} required disabled={blocked}/></label><p>Do not enter card numbers, credentials, or unnecessary personal details. Card authorization holds are not received funds. A receipt reduction corrects a mistaken receipt record; it does not return money.</p><button className="primary" disabled={blocked||data.version>=1000}>Review deposit entry</button>{data.version>=1000&&<p>This book has reached its 1,000-entry limit. Its full history remains available.</p>}</form>}
  {proposal&&canWrite&&<section className="pilot-settings"><h3>Review security-deposit entry</h3><p><strong>{depositKinds[proposal.command.kind]} · {reportUsd(proposal.command.amount_minor)}</strong></p><p>{proposal.command.reference} · {proposal.command.reason}</p><p>{proposal.command.method?depositMethods[proposal.command.method]:'Record correction with no money movement'} · Recording date {proposal.command.expected_recording_date} · {proposal.command.expected_recording_time_zone}</p>{proposal.review.target_remaining_minor!==null&&<p>Original receipt has {reportUsd(proposal.review.target_remaining_minor)} remaining recorded funds before this entry.</p>}<form onSubmit={e=>{e.preventDefault();confirm()}}><label className="pilot-check"><input type="checkbox" required disabled={blocked}/>{proposal.command.kind==='receipt_reduction'?'I verified this is a receipt record error; no refund or other money movement occurred.':'I verified this receipt or refund in the external transaction record. This is received or returned money, not a card hold.'}</label><button className="primary" disabled={blocked}>Confirm security-deposit entry</button><button type="button" className="secondary" disabled={blocked} onClick={()=>setProposal(null)}>Edit entry review</button></form></section>}
  <p className="muted">Applying deposits to a bill, damage decisions, correcting a mistaken refund, or undoing a receipt reduction require separate workflows. Do not enter a fictional receipt to balance an error.</p>
 </section>;
}
